package structural.flyweight.sample;

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Tree> forest = new ArrayList<>();

        forest.add(new Tree(1, 2, TreeFactory.getTreeType("Oak", "Green")));
        forest.add(new Tree(3, 4, TreeFactory.getTreeType("Oak", "Green"))); // reuses cached TreeType
        forest.add(new Tree(5, 6, TreeFactory.getTreeType("Pine", "DarkGreen")));

        for (Tree tree : forest) {
            tree.draw();
        }
    }
}

package structural.flyweight.sample;

// Context — extrinsic, per-instance state (position), plus a reference to the shared flyweight.
public class Tree {
    private final int x;
    private final int y;
    private final TreeType type;

    public Tree(int x, int y, TreeType type) {
        this.x = x;
        this.y = y;
        this.type = type;
    }

    public void draw() {
        type.draw(x, y);
    }
}

package structural.flyweight.sample;

import java.util.HashMap;
import java.util.Map;

// Caches one TreeType per (name, color) combination instead of creating a new one every time.
public class TreeFactory {
    private static final Map<String, TreeType> treeTypes = new HashMap<>();

    public static TreeType getTreeType(String name, String color) {
        String key = name + "-" + color;
        TreeType type = treeTypes.get(key);
        if (type == null) {
            type = new TreeType(name, color);
            treeTypes.put(key, type);
            System.out.println("Created new TreeType: " + key);
        }
        return type;
    }
}

package structural.flyweight.sample;

// Flyweight — intrinsic, shared state (identical for every tree of this type).
public class TreeType {
    private final String name;
    private final String color;

    public TreeType(String name, String color) {
        this.name = name;
        this.color = color;
    }

    public void draw(int x, int y) {
        System.out.println("Drawing " + name + " (" + color + ") at (" + x + ", " + y + ")");
    }
}

